reviews.css:
:host{all:initial;color-scheme:dark}
dialog{box-sizing:border-box;width:min(460px,calc(100vw - 32px));max-height:calc(100vh - 40px);overflow:auto;border:1px solid #ffffff28;border-radius:16px;padding:26px;background:rgb(24 24 24 / .55);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);color:#dfdfdf;box-shadow:0 24px 70px #0006;font:14px/1.6 "OpenAI Sans", "OpenAI Sans Variable", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif}
dialog::backdrop{background:#0003}
.brand-row{display:flex;align-items:center;justify-content:space-between;gap:12px}
.brand{color:#45d6c8;font-size:12px;font-weight:500;letter-spacing:1.7px;text-transform:uppercase;white-space:pre-wrap}
.brand-icon{display:block;flex:0 0 24px;width:24px;height:24px;background:#45d6c8;mask:url("data:image/png;base64,") center/contain no-repeat}
h2{font-size:20px;line-height:1.25;letter-spacing:-.6px;margin:20px 0 12px}
.count{color:#ff6b6b}
p{margin:10px 0;color:#bcbcbc}p.policy{font-size:12px}
.actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:28px}
button{display:inline-flex;align-items:center;justify-content:center;gap:6px;flex:1;min-width:90px;box-sizing:border-box;height:34px;border:0;outline:none;box-shadow:none;border-radius:999px;padding:0 16px;background:#303030;color:#dfdfdf;font:500 13px "OpenAI Sans", "OpenAI Sans Variable", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;cursor:pointer}
.button-icon{width:14px;height:14px;flex:0 0 14px;pointer-events:none}
button:focus-visible{filter:brightness(1.2)}
button.mask{background:#1f6fc7;color:#fff}
button.send{color:#fff;background:#b4232d}
button:disabled{opacity:.45;cursor:not-allowed}

